package com.medtrack.inventory.entity; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(nullable=false) private String action; @Column(name="entity_name",nullable=false) private String entityName; @Column(name="entity_id",nullable=false) private UUID entityId; @Column(name="changes_json",nullable=false) private String changesJson; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); protected AuditLog(){} public AuditLog(UUID user,String action,String name,UUID id,String changes){userId=user;this.action=action;entityName=name;entityId=id;changesJson=changes;} }
